[ExtensionOf(tableStr(VendInvoiceJournalLineEntity))]
public final class METVendInvoiceJournalLineEntity_Extension
{


}

Method.Source:
/// <summary>
/// MPJ_3316_Nathan AP Inv Acknowledgment
/// populating METGSTAmount
/// </summary>
public void postLoad()
{
    next postload();
    this.METGSTAmount = this.getMETGSTAmount();
}

    /// <summary>
    /// MPJ_3316_Nathan AP Inv Acknowledgment
    /// Get GST amount from custinvoicejour
    /// METPosted and METLedgerJournalTransRecId required to validate and filter query below. Both fields are set as internal and
    /// not visible to the user.
    /// </summary>
    /// <returns>TaxAmount returns METGSTAmount</returns>
    public TaxAmount getMETGSTAmount()
    {
        TaxAmount taxAmount = 0;
        
        //Line has to be posted to provide GST amount
        if (this.METPosted == NoYes::Yes)
        {
            changecompany(this.DataAreaId)
            {
                taxAmount   = Tax::taxTotalVoucherDateRecId(this.Voucher, this.Date, this.RecId);
            }
        }

        return abs(taxAmount);
    }
